// ENGINEERING FORGE — the contract of the lazy per-route data (design §5.2). FROZEN in Phase 0: the files
// src/forge/data/routes/<slug>.json are generated by scripts/forge/extract-maestro.mjs and every other
// branch programs against these types (and against the two-route fixture in src/forge/__tests__/fixtures/routes/).
import type { ForgeCapability } from "@/core/forge-verdict";
import type { ForgePathSlug } from "@/forge/ids";

export type ForgeFamily =
  | "Fundamentos"
  | "Sistemas y diseño"
  | "Plataforma Foundry/AIP"
  | "Oficio FDE"
  | "Profundidad SWE"
  | "Evaluación";

/** What a cell paints (the flow). The table of §5.2 is the only source; nothing is inferred. */
export type ForgeFlujo = "mision" | "entrevista" | "expediente" | "diagnostico" | "proyecto" | "ontologia" | "gameday";

/** The ONLY verdict kind that opens the cell (§8.1); null in D1–D8. */
export type ForgeCompuerta = "mision" | "entrevista" | "expediente" | "ontologia" | "gameday" | null;

export type ForgeCellClass = "ruta" | "diagnostico" | "reto" | "expediente";

export interface SourceRef {
  /** the key of the link label in the master program («F0-01 · FDE · A Day…» → "FDE"), or "" */
  clave: string;
  etiqueta: string;
  /** exact URL, parameters included */
  url: string;
  tipo: "docs" | "curso" | "paper" | "blog" | "video" | "comunitario" | "otro";
  acceso: "publico" | "instancia" | "cuenta" | "pago";
}

/** Keys of the honesty texts of §5.5 (the texts live in src/forge/data/labels.json). */
export type HonestyLabel =
  | "video_no_revisado"
  | "requiere_cuenta"
  | "acceso_comunidad"
  | "formato_practica"
  | "reto_propio"
  | "inspirado_catalogo"
  | "seleccion_curso"
  | "transcripcion_f106";

export interface DiagnosticTask {
  /** minutes of §13 (visible, never blocks) */
  minutos: number;
  /** the full statement of §13, verbatim */
  enunciado: string;
  /** «Aplicación» of §13 (two sessions, first pass without AI, record before checking), verbatim */
  aplicacion?: string;
  /** «Salida del diagnóstico» of §13 (eight observations, no global score), verbatim */
  salida?: string;
}

export interface RetoData {
  reto: string;
  /** «Entregable y condición de defensa» of §09, verbatim */
  entregable: string;
}

export interface ExpedienteCase {
  decision: string;
  /** keys of «Fuentes de fundamento» (resolved in catalog.json) */
  claves: string[];
  entregable: string;
  inspiradoEnCatalogo: boolean;
  /** «Plantilla exigida a cada expediente» of §08, verbatim */
  plantilla?: string;
  /** «Tres pasadas» of §08, verbatim */
  pasadas?: string;
}

/** A field of a §10 project or a §11 pilot, verbatim («**Etiqueta:** texto»; lists become items). */
export interface MaestroField {
  etiqueta: string;
  texto: string;
  items?: string[];
}

export interface ForgeCellData {
  code: string;
  id: string;
  title: string;
  cls: ForgeCellClass;
  flujo: ForgeFlujo;
  compuerta: ForgeCompuerta;
  ficha: {
    foco?: string;
    resultado?: string;
    fuentes: SourceRef[];
    mision: string;
    defensa: string;
    transferencia?: string;
    variante?: string;
  };
  /** the compuerta's question and rubric, only when compuerta !== null. Assembled ONLY from the master program:
   *  the fiche's defence (X: deliverable and defence condition; SD: its deliverable), the approval rule and the
   *  scale of §05, the literal trace of each essential capability and critical condition, and (F2) the project's
   *  acceptance of §10. */
  gate?: { pregunta: string; rubrica: string[] };
  /** F2-01…F2-06: the project of §10, verbatim (brief, inputs, construction, incidents, acceptance…) */
  proyecto?: { n: number; titulo: string; campos: MaestroField[] };
  /** essential capabilities, ≥ 1 */
  capacidades: ForgeCapability[];
  /** one literal phrase of the fiche per declared capability */
  rastroCapacidades: Partial<Record<ForgeCapability, string>>;
  /** ≥ 1; ids of §05 or `otra:<slug>` */
  criticas: { id: string; texto: string; rastro: string }[];
  naturaleza: { valor: "a_mano" | "delegable" | "mixto"; rastro?: string; parts?: { name: string; nature: "a_mano" | "delegable" }[] };
  alcance: "local" | "local+nativa";
  requireEnglish?: true;
  /** only A1 and A2 */
  equivalencias?: { celdas: string[] } | { sinEquivalente: true };
  /** X and SD: codes of cells or projects that use them */
  usadoEn?: string[];
  etiquetas: HonestyLabel[];
  d?: DiagnosticTask;
  x?: RetoData;
  sd?: ExpedienteCase;
}

export interface ForgeRouteData {
  v: 1;
  slug: ForgePathSlug;
  code: string;
  name: string;
  family: ForgeFamily;
  header: {
    entrada: string;
    /** codes (cells or routes) named by «Entrada»; shown as «Entrada recomendada», never a lock */
    entradaRecomendada: string[];
    evidencia: string;
    apoyo: SourceRef[];
  };
  cells: ForgeCellData[];
  /** sha256[:10] of the master program file the data was extracted from */
  maestro_sha10: string;
}
